// Check for overlap first
bool overlapX = !(box1.Max.X < box2.Min.X || box2.Max.X < box1.Min.X);
bool overlapY = !(box1.Max.Y < box2.Min.Y || box2.Max.Y < box1.Min.Y);
bool overlapZ = !(box1.Max.Z < box2.Min.Z || box2.Max.Z < box1.Min.Z);

if (overlapX && overlapY && overlapZ) {
    return BoxRelation::Overlapped;
}

// Check for adjacency - boxes touch on at least one face/edge/corner
bool adjacentX = (box1.Max.X == box2.Min.X) || (box2.Max.X == box1.Min.X);
bool adjacentY = (box1.Max.Y == box2.Min.Y) || (box2.Max.Y == box1.Min.Y);
bool adjacentZ = (box1.Max.Z == box2.Min.Z) || (box2.Max.Z == box1.Min.Z);

// Check if boxes are adjacent in any dimension while overlapping in others
bool adjacent = (adjacentX && overlapY && overlapZ) ||
                (adjacentY && overlapX && overlapZ) ||
                (adjacentZ && overlapX && overlapY) ||
                (adjacentX && adjacentY && overlapZ) ||
                (adjacentX && adjacentZ && overlapY) ||
                (adjacentY && adjacentZ && overlapX) ||
                (adjacentX && adjacentY && adjacentZ);

if (adjacent) {
    return BoxRelation::Adjacent;
}

// Otherwise they are separated
return BoxRelation::Separated;

